mapper.sql:
where latest.user_id = #{userId} and latest.is_correct = 0

    and q.stem like concat('%', #{query.keyword}, '%')


    and q.question_type = #{query.questionType}


    and q.difficulty = #{query.difficulty}


    and JSON_CONTAINS(q.knowledge_points, JSON_QUOTE(#{query.knowledgePoint}))

mapper.select:
select * from quiz_record
where user_id = #{userId}
  and coalesce(answer_time, create_time) >= date_sub(curdate(), interval (#{days} - 1) day)
order by coalesce(answer_time, create_time) desc, id desc
limit #{limit}
